-- Uses the value added by the previous migration: only works if that one was committed on its own.
insert into public.todos (user_id, priority) select id, 1 from public.profiles where role = 'owner';

-- A table created after todos that todos then points at: seeding must follow the keys.
create table public.workspaces (
  id bigint generated by default as identity primary key,
  name text not null,
  seats int not null check (seats > 10),
  balance numeric not null check (balance < 0),
  discount numeric not null check (discount <= 0.5)
);
alter table public.workspaces enable row level security;
alter table public.todos add column workspace_id bigint not null references public.workspaces;
-- ...and profiles and todos now point at each other.
alter table public.profiles add column favourite_todo uuid references public.todos;

create table public.announcements (
  id bigint generated by default as identity primary key,
  body text not null
);
alter table public.announcements enable row level security;
create policy "Visitors see announcements" on public.announcements
  for select using (auth.role() = 'anon' and auth.jwt() ->> 'role' = 'anon');

create table public.staff_notes (
  id bigint generated by default as identity primary key,
  body text not null
);
alter table public.staff_notes enable row level security;
create policy "Signed-in users only" on public.staff_notes
  for select using (auth.role() = 'authenticated');

create table public.share_links (
  id bigint generated by default as identity primary key,
  url text not null
);
alter table public.share_links enable row level security;
-- Calls an extension function unqualified, as Supabase's search path allows.
create policy "Anyone with a token" on public.share_links
  for select using (length(gen_random_bytes(4)) = 4);

-- Sorts before both tables of the profiles/todos cycle and needs a todo to exist.
create table public.attachments (
  id bigint generated by default as identity primary key,
  todo_id uuid not null references public.todos on delete cascade
);
alter table public.attachments enable row level security;
